"""Top-up for the 12 expanded courses: a case-study class and an interview-practice / troubleshooting class for each."""
from coursekit import ill_flow, ill_cycle, ill_quad, ill_stack
from expand import extend
from exp_a import tb

def case(title, goal, body, take, ex): return ("advanced", title, goal, body, take, ex)
def prep(title, goal, body, take, ex): return ("advanced", title, goal, body, take, ex)

def Q(q, a, why): return f'<div class="box"><b>Q. {q}</b><br><b>Model answer:</b> {a}<br><span class="small"><i>Why it works: {why}</i></span></div>'

TOP = {}

